    "Durchsucht Dateiinhalte per regulärem Ausdruck. Gibt Treffer als 'relpath:lineno: line' zurück. Optional auf ein Unterverzeichnis und auf Dateien einschränkbar, die zu einem glob passen (z. B. '*.py').",
