  "mcp.title": "MCP / Integracje",
  "mcp.servers": "skonfigurowane: {n}",
  "mcp.empty":
    "Brak skonfigurowanych serwerów MCP. Dodaj jeden tutaj albo przez `chimera mcp add`. CLI jest źródłem prawdy — aplikacja jest tylko widokiem na nie.",
  "mcp.addServer": "Dodaj serwer",
  "mcp.add": "Dodaj",
  "mcp.catalog.title": "Podłącz usługę",
  "mcp.entry.github.summary": "Czytanie repozytoriów, zgłoszeń i pull requestów — kodu i rozmowy wokół niego.",
  "mcp.entry.github.containment": "Tryb tylko do odczytu jest włączony, a serwer stawia go ponad każdym innym ustawieniem. Nic nie jest zapisywane: token żyje w pamięci serwera i nigdy nie trafia na dysk ani do Chimery.",
  "mcp.entry.githubBinary.summary": "Ten sam serwer GitHuba, uruchamiany bezpośrednio zamiast przez Dockera.",
  "mcp.entry.githubBinary.containment": "Tryb tylko do odczytu jest włączony. Logowanie odbywa się w serwerze, więc token nigdy nie trafia do Chimery; bez przeglądarki serwer przechodzi na kod urządzenia.",
  "mcp.entry.firebase.summary": "Odpytywanie Firestore, Auth, Storage i reszty projektu Firebase.",
  "mcp.entry.firebase.containment": "Działa jako ten, kto uruchomił firebase login na tej maszynie, więc granicą są uprawnienia tego konta. Nie ma przełącznika tylko do odczytu — oznaczenia przy narzędziach to wskazówki dla klienta, a nie coś, co serwer egzekwuje.",
  "mcp.entry.supabase.summary": "Odczyt projektu Supabase: schemat, dane, edge functions i dokumentacja.",
  "mcp.entry.supabase.containment": "Tylko do odczytu i zawężone do bazy i dokumentacji, jedno i drugie egzekwowane przez Supabase, a nie wskazówką, którą klient może zignorować. Logowanie odbywa się w przeglądarce, więc nie ma klucza do przechowania. Do serwera dociera przez zewnętrzny most mcp-remote.",
  "mcp.entry.db.summary": "Przeglądanie i odpytywanie bazy {n}: nazwy tabel, schematy i SQL.",
  "mcp.entry.db.containment": "Ten serwer NIE ma trybu tylko do odczytu i zatwierdza każdą instrukcję natychmiast — DROP wykona się naprawdę. Ogranicza go wyłącznie użytkownik bazy w adresie połączenia, więc wskaż takiego, który ma tylko uprawnienia, jakie możesz stracić.",
  "mcp.catalog.lead": "Gotowe serwery, każdy sprawdzony w jego własnej dokumentacji. Wybór wypełnia formularz poniżej — nic nie zapisuje się do czasu kliknięcia Dodaj.",
